ote": "1 Year Comprehensive Vehicle Warranty", "range_km": 45, "top_speed_kmph": 25, "charging_time": "5-7 hrs", "battery_capacity": "As per config (see price list)", "motor_power": "As per config", "load_capacity_kg": 100, "highlights": ["Specially configured mobility vehicle", "Suitable for accessibility use cases", "Ex-factory price band per Oleant price list (Aug 2026)", "Price includes GST (RTO/insurance extra)"], "hero_image": "assets/scooters/oleant_handicapped.png", "slug": "oleant-handicapped", "colors": [["White", 4294967295], ["Blue", 4278190335]], "image": "assets/scooters/oleant_handicapped.png"}]', true);

    $inserted = 0;
    $updated = 0;

    foreach ($products as $idx => $p) {
        $existing = db_fetch_one("SELECT id FROM products WHERE org_id = ? AND model_code = ?", [$orgId, $p['model_code']]);

        if ($existing) {
            $productId = $existing['id'];
            // Update hero_image and slug if missing
            db_execute(
                "UPDATE products SET slug = ?, hero_image = ?, highlights = ?, updated_at = ? WHERE id = ?",
                [$p['slug'], $p['hero_image'], json_encode($p['highlights']), $now, $productId]
            );
            $updated++;
        } else {
            $productId = Uuid::v4();
            db_execute(
                "INSERT INTO products (
                    id, org_id, category, brand, name, model_code, rating, warranty_years, warranty_note,
                    range_km, top_speed_kmph, charging_time, battery_capacity, motor_power, load_capacity_kg,
                    highlights, active, listed_at, created_by, updated_at, is_featured, featured_order, slug, hero_image
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?, ?, ?, ?)",
                [
                    $productId, $orgId, $p['category'], $p['brand'], $p['name'], $p['model_code'],
                    $p['rating'], $p['warranty_years'], $p['warranty_note'], $p['range_km'],
                    $p['top_speed_kmph'], $p['charging_time'], $p['battery_capacity'], $p['motor_power'],
                    $p['load_capacity_kg'], json_encode($p['highlights']), $now, $adminId, $now,
                    $idx < 6 ? 1 : 0, $idx, $p['slug'], $p['hero_image']
                ]
            );
            $inserted++;
        }

        // Seed colors & images
        foreach ($p['colors'] as $pos => [$cName, $argb]) {
            $cRow = db_fetch_one("SELECT id FROM product_colors WHERE product_id = ? AND name = ?", [$productId, $cName]);
            if (!$cRow) {
                $colorId = Uuid::v4();
                db_execute(
                    "INSERT INTO product_colors (id, product_id, name, argb, in_stock, position) VALUES (?, ?, ?, ?, 1, ?)",
                    [$colorId, $productId, $cName, $argb, $pos]
                );
            } else {
                $colorId = $cRow['id'];
            }

            // Primary cutout image
            $imgRow = db_fetch_one("SELECT id FROM product_color_images WHERE color_id = ? AND position = 0", [$colorId]);
            if (!$imgRow) {
                db_execute(
                    "INSERT INTO product_color_images (id, color_id, url, position) VALUES (?, ?, ?, 0)",
                    [Uuid::v4(), $colorId, $p['image']]
                );
            }
        }
    }

    echo "  brochure catalogue seeded: {$inserted} inserted, {$updated} updated (total models: " . count($products) . ")\n";
};
